// Set Window — compute the brief's date window in Asia/Manila. Runs once per brief.
const now = DateTime.now().setZone('Asia/Manila');
const today = now.startOf('day');
const yesterday = today.minus({ days: 1 });
return [{
  json: {
    today: today.toISODate(),
    yesterday: yesterday.toISODate(),
    seriesFrom: yesterday.minus({ days: 29 }).toISODate(),
    subsUntil: today.plus({ days: 7 }).toISODate(),
    todayEndIso: today.endOf('day').toISO(),
    tz: 'Asia/Manila'
  }
}];

// Build v2 Sections — the three new sections of the morning brief as Telegram HTML.
// Every source is optional: a failed or empty source yields one labelled line, never an error.
const SHOW_EMPTY_SUBS = false;   // true = print "0 subscriptions defined" every morning
const MAX_TASKS = 5;
const TASK_TAG = 'ecosystem';
const TZ = 'Asia/Manila';

const win = $('Set Window').first().json;
const today = DateTime.fromISO(win.today, { zone: TZ });
const todayEnd = DateTime.fromISO(win.todayEndIso, { zone: TZ });

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const peso = (n) => '₱' + Math.round(Number(n) || 0).toLocaleString('en-PH');
const pick = (o, keys) => {
  for (const k of keys) if (o && o[k] !== undefined && o[k] !== null && o[k] !== '') return o[k];
  return undefined;
};
const fmtDay = (d) => (d && d.isValid ? d.setZone(TZ).toFormat('ccc d LLL') : '?');

// Read a source node's output. onError=continueRegularOutput makes a failed HTTP node emit
// one item whose json.error is set; a node that never ran throws — both become a label.
function read(nodeName) {
  try {
    const items = $(nodeName).all().map((i) => i.json);
    if (items.length === 1 && items[0] && items[0].error) {
      return { error: String(items[0].error.message || items[0].error), items: [] };
    }
    return { error: null, items };
  } catch (e) {
    return { error: 'not executed', items: [] };
  }
}

// ---- Tasks (TickTick Open API: GET /open/v1/project/{id}/data -> { project, tasks, columns })
function tasksSection() {
  const src = read('TickTick Inbox Data');
  if (src.error) return `<b>✅ Tasks</b>\n<i>TickTick unavailable (${esc(src.error)})</i>`;
  const raw = src.items.flatMap((j) => (Array.isArray(j.tasks) ? j.tasks : Array.isArray(j) ? j : []));
  const open = raw.filter((t) => Number(t.status) === 0);
  const due = (t) => (t.dueDate ? DateTime.fromISO(t.dueDate, { zone: TZ }) : null);
  const relevant = open.filter((t) => (t.tags || []).includes(TASK_TAG) || (due(t) && due(t) <= todayEnd));
  if (!relevant.length) return `<b>✅ Tasks</b>\nnothing tagged #${TASK_TAG} or due today`;
  relevant.sort((a, b) => {
    const da = due(a), db = due(b);
    const oa = da && da < today ? 0 : 1, ob = db && db < today ? 0 : 1;
    if (oa !== ob) return oa - ob;                                    // overdue first
    if ((b.priority || 0) !== (a.priority || 0)) return (b.priority || 0) - (a.priority || 0); // then priority
    return (da ? da.toMillis() : Infinity) - (db ? db.toMillis() : Infinity);                  // then soonest
  });
  const lines = relevant.slice(0, MAX_TASKS).map((t) => {
    const d = due(t);
    const flag = d && d < today ? '⚠️ ' : d && d <= todayEnd ? '📌 ' : '• ';
    const when = d ? ` <i>(${d < today ? 'overdue ' : ''}${fmtDay(d)})</i>` : '';
    return `${flag}${esc(t.title)}${when}`;
  });
  const more = relevant.length > MAX_TASKS ? `\n<i>+${relevant.length - MAX_TASKS} more</i>` : '';
  return `<b>✅ Tasks</b> (${relevant.length} open)\n${lines.join('\n')}${more}`;
}

// ---- Subscriptions (MoneyMatter upcoming payments: name, expected amount, currency, next payment date, category)
function subsSection() {
  const src = read('MoneyMatter Subscriptions Upcoming');
  if (src.error) return `<b>🔁 Subscriptions ≤7 d</b>\n<i>MoneyMatter unavailable (${esc(src.error)})</i>`;
  const rows = src.items
    .flatMap((j) => (Array.isArray(j) ? j : Array.isArray(j.data) ? j.data : Array.isArray(j.items) ? j.items : [j]))
    .filter((r) => r && typeof r === 'object' && Object.keys(r).length);
  const until = DateTime.fromISO(win.subsUntil, { zone: TZ }).endOf('day');
  const dueSoon = rows
    .map((r) => {
      const when = pick(r, ['nextPaymentDate', 'nextExpectedPaymentDate', 'nextDate', 'dueDate']);
      return {
        name: pick(r, ['name', 'subscriptionName', 'payee']),
        amt: pick(r, ['expectedAmount', 'amount']),
        cur: pick(r, ['currency', 'currencyCode']) || 'PHP',
        when: when ? DateTime.fromISO(String(when), { zone: TZ }) : null
      };
    })
    .filter((r) => r.when && r.when.isValid && r.when <= until)
    .sort((a, b) => a.when - b.when);
  if (!dueSoon.length) {
    if (!rows.length && !SHOW_EMPTY_SUBS) return '';
    return `<b>🔁 Subscriptions ≤7 d</b>\n${rows.length
      ? 'none due this week'
      : '<i>0 subscriptions defined in MoneyMatter — the sheet recurring list above is the source</i>'}`;
  }
  const total = dueSoon.reduce((s, r) => s + (Number(r.amt) || 0), 0);
  const lines = dueSoon.map((r) => {
    const days = Math.round(r.when.startOf('day').diff(today, 'days').days);
    const amt = r.cur === 'PHP' ? peso(r.amt) : `${r.cur} ${Number(r.amt || 0).toFixed(2)}`;
    return `• ${esc(r.name)} — ${amt} · ${fmtDay(r.when)} <i>(${days <= 0 ? 'today' : 'in ' + days + ' d'})</i>`;
  });
  return `<b>🔁 Subscriptions ≤7 d</b> · ${peso(total)}\n${lines.join('\n')}`;
}

// ---- Yesterday's spend (Hermes tool spend_series, daily granularity, last 30 days ending yesterday)
function spendSection() {
  const src = read('Yesterday Spend (spend_series)');
  if (src.error) return `<b>💸 Yesterday</b>\n<i>spend_series unavailable (${esc(src.error)})</i>`;
  const j = src.items[0] || {};
  const body = j.result ?? j.data ?? j;
  const series = pick(body, ['series', 'points', 'rows', 'days']) || (Array.isArray(body) ? body : []);
  if (!Array.isArray(series) || !series.length) return `<b>💸 Yesterday</b>\n<i>no series returned</i>`;
  const norm = series.map((p) => ({
    date: String(pick(p, ['date', 'day', 'period', 'x']) || '').slice(0, 10),
    amount: Math.abs(Number(pick(p, ['amount', 'total', 'spend', 'value', 'y'])) || 0),
    top: pick(p, ['topCategory', 'top', 'category'])
  }));
  const y = norm.find((p) => p.date === win.yesterday);
  const yAmt = y ? y.amount : 0;
  const others = norm.filter((p) => p.date !== win.yesterday);
  const avg = others.length ? others.reduce((s, p) => s + p.amount, 0) / others.length : null;
  let verdict = '';
  if (avg !== null && avg > 0) {
    const ratio = yAmt / avg;
    verdict = ratio >= 2 ? ' 🔴 2× your 30-day average'
      : ratio >= 1.25 ? ' 🟠 above average'
      : ratio <= 0.25 ? ' 🟢 quiet day'
      : ' · about average';
  }
  const top = y && y.top ? `\n<i>top: ${esc(y.top)}</i>` : '';
  const avgLine = avg !== null ? `\n30-day avg ${peso(avg)}/day` : '';
  return `<b>💸 Yesterday</b> (${fmtDay(DateTime.fromISO(win.yesterday, { zone: TZ }))})\n${peso(yAmt)}${verdict}${avgLine}${top}`;
}

const sections = [tasksSection(), subsSection(), spendSection()].filter(Boolean);
return [{ json: { v2Html: sections.join('\n\n'), sections, window: win } }];
